// Additive workflow. Existing labs, accounts, profiles and old research fields remain intact.
const legacyScience={bind,home,topics,project,review,feedbackPage,portfolio,diagnostic,diagnosticResult,render,progress,messageList,load,persist};
const SCI_STEPS=[['diagnostic','Тіркелу және диагностика'],['topics','Тақырып таңдау кестесі'],['contest','Конкурс және ережелер'],['project','Ғылыми жобаны жазу'],['home','Менің жұмыс жолым (тренажер)'],['checks','Талаптарды тексеру'],['feedback','Мұғалімнің кері байланысы'],['export','Word-қа жүктеу']];
NAV_STUDENT.splice(0,NAV_STUDENT.length,...SCI_STEPS.map(([id,label],i)=>[id,String(i+1),label]),['messages','✉','Хабарламалар'],['labs','⬡','Виртуалды зертхана'],['experiments','↗','Тәжірибе және күнделік'],['directions','✧','Алты зерттеу бағыты'],['profile','◉','Профиль'],['portfolio','▣','Портфолио']);
NAV_TEACHER.splice(3,0,['messages','✉','Хабарламалар']);
let sciBusy=false;
function sciField(key,label,value='',type='input',required=false,max=12000){return `<label class="field">${label}<${type} data-sci="${key}" ${type==='input'?'value="'+esc(value)+'"':''} ${required?'required':''} maxlength="${max}">${type==='textarea'?esc(value):''}</${type}></label>`}
function sciNotice(t){return `<div class="note">${t}</div>`}
function sciHeader(t,d){return heading(t,d)+`<div class="science-route">${SCI_STEPS.map(([p,l],i)=>`<button class="${page===p?'active':''}" data-go="${p}"><b>${i+1}</b><span>${l}</span></button>`).join('')}</div>`}
function sciSaveMessage(text){return `<div class="oneline"><button class="btn primary" id="sci-save">${text||'Өзгерістерді сақтау'}</button><span class="micro" id="sci-save-state">Өзгерістер автоматты сақталады</span></div>`}
function sciRows(w=work,rows=feedback){return rows.filter(r=>r.student_id===(user?.role==='teacher'?selectedStudent:user?.id)||demo)}
function sciStatus(w=work,rows=feedback){const s=science(w),r=w.submitted?sciLatestReview(w,rows):null;if(s.submission&&!w.submitted)return 'Жоба өзгертілген · қайта жіберу қажет';return r?.decision==='returned'?'Түзетуге қайтарылды':r?.decision==='approved'?'Мұғалім қабылдады':s.submission&&w.submitted?'Мұғалім қарап жатыр':sciTopicDecision(w,rows)?.decision==='approved'?'Тақырып мақұлданды':'Жоба дайындалуда'}
progress=function(w=work){if(!w.science)return legacyScience.progress(w);const all=sciChecks(w,user?.role==='teacher'?rosterFeedback.filter(r=>r.student_id===selectedStudent):feedback).filter(x=>!x.manual);return Math.round(all.filter(x=>x.ok).length/all.length*100)};
home=function(){const s=science();return sciHeader('5. Менің жұмыс жолым (тренажер)','Өз идеяңды зерттеуге айналдыр. Әр қадам сақталады, мұғалім көмектеседі.')+`<section class="hero"><div class="hero-content"><span class="eyebrow">ҒЫЛЫМИ ЖОБАҢНЫҢ ЖОЛЫ</span><h2>${esc(work.topic?.title||'Қызығушылықтан зерттеуге дейін')}</h2><p>${esc(sciStatus())}</p><button class="btn light" data-go="${!work.diagnostic?'diagnostic':!work.topic?'topics':!s.contest?'contest':'project'}">Жұмысты жалғастыру →</button></div><div class="hero-art"><div class="orbit"><div class="star">✦</div></div></div></section><div class="stats"><div class="stat"><div><b>${progress()}%</b><small>Автоматты тексерілетін тармақтар</small></div></div><div class="stat"><div><b>${sciContest()?.name||'Таңдалмаған'}</b><small>Ғылыми жоба конкурсы</small></div></div><div class="stat"><div><b>${work.journal.length}</b><small>Күнделік жазбасы</small></div></div></div><section class="card science-section"><h2>Тренажерде жаттығу</h2><ol><li>Бағытыңа сәйкес зертхананы ашып, алғашқы нұсқаны жаса.</li><li>Бір факторды өзгерт, нәтижені салыстыр.</li><li>Тәжірибені күнделікке тірке және жобаңа түсіндір.</li></ol><button class="btn primary" data-go="labs">Тренажерді ашу →</button><button class="btn" data-go="experiments">Нәтижені тіркеу →</button></section><div class="section-row"><h2>Өнім жаса, сына, дәлелде</h2></div>${trackTiles()}`};
const JUNIOR_SKILLS=[{q:'Қораптың макетін жасау үшін алдымен не керек?',o:['Өлшемін білу','Түсін ғана таңдау','Бірден желімдеу','Кездейсоқ құрастыру'],a:0,e:'Макет үшін заттың өлшемін білу қажет.'},{q:'Қай батырма не істейтінін анық түсіндіреді?',o:['Мұнда','Бас','Жобаны сақтау','OK'],a:2,e:'Батырма атауы әрекетті анық көрсетеді.'},{q:'Ойыншық робот алдындағы кедергіге жақындады. Не істеу керек?',o:['Кедергіге қарай жүру','Тоқтап, қауіпсіз жол таңдау','Көзді жұму','Жылдамдығын арттыру'],a:1,e:'Қауіпсіз жолды таңдау керек.'},{q:'Алдымен 2 текше, кейін тағы 3 текше қостың. Барлығы қанша?',o:['2','3','5','6'],a:2,e:'2 + 3 = 5.'},{q:'Қимылды мультфильм неден құралады?',o:['Бір ғана дыбыстан','Бос беттен','Тек саннан','Бірінен кейін бірі көрсетілген суреттерден'],a:3,e:'Суреттер ретімен көрсетілгенде қозғалыс әсері пайда болады.'},{q:'Компьютерге алма мен алмұртты ажыратуды қалай түсіндіреміз?',o:['Ештеңе көрсетпейміз','Атауы дұрыс жазылған әртүрлі мысалдар көрсетеміз','Кез келген жауапты дұрыс дейміз','Тек бір қате сурет көрсетеміз'],a:1,e:'Дұрыс белгіленген мысалдар керек.'}];
function sciJunior(){return Number(science().grade)<=4&&Number(science().grade)>=2}
diagnostic=function(){const s=science();if(!s.grade||!s.interests)return sciHeader('1. Өзіңді таныстыр','Қай сыныпта оқисың? Нені зерттеп көргің келеді?')+`<section class="card wide"><form id="sci-onboarding"><label class="field">Сыныбың<select name="grade" required><option value="">Таңда</option>${Array.from({length:11},(_,i)=>i+2).map(n=>`<option ${String(s.grade||profileData.grade)===String(n)?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Қызығушылығың<textarea name="interests" required maxlength="1000" placeholder="Не құрастыру, бақылау немесе салыстыру ұнайды?">${esc(s.interests||profileData.bio)}</textarea></label><button class="btn primary">Сақтау және диагностикаға өту →</button></form></section>`;if(!sciJunior())return sciHeader('1. Бастапқы диагностика',s.grade+'-сынып · Қызығушылық пен бастапқы дағды бөлек көрсетіледі.')+legacyScience.diagnostic();if(work.diagnostic&&(diagStep===0||diagStep>=18))return diagnosticResult();const questions=TRACKS.flatMap(t=>t.interest);const skillMode=diagStep>=12,item=JUNIOR_SKILLS[diagStep-12];return sciHeader('1. Қызығушылығыңды байқа','2–4 сыныпқа арналған қысқа, түсінікті сұрақтар. Қажет болса, мұғалім сұрақты оқып береді.')+`<section class="card wide"><span class="pill">${diagStep+1} / 18</span><div class="progress"><span style="width:${diagStep/18*100}%"></span></div><h2>${esc(skillMode?item.q:questions[diagStep])}</h2><p class="muted">${skillMode?'Білмесең, «Әзірге білмеймін» таңда.':'Қызығатыныңды таңда. Дұрыс не бұрыс жауап жоқ.'}</p><div class="answers">${(skillMode?[...item.o,'Әзірге білмеймін']:['Қызық емес','Аздап қызық','Қызық','Өте қызық']).map((v,i)=>`<button class="answer ${diagAnswers[diagStep]===i?'selected':''}" data-diag="${i}">${esc(v)}</button>`).join('')}</div><div class="row spread"><button class="btn" id="diag-prev" ${diagStep===0?'disabled':''}>← Алдыңғы</button><button class="btn primary" id="diag-next" ${diagAnswers[diagStep]===undefined?'disabled':''}>${diagStep===17?'Нәтижені сақтау':'Келесі →'}</button></div></section>`};
diagnosticResult=function(){const s=science(),d=work.diagnostic;if(!d)return sciNotice('Диагностиканы аяқта.');const ordered=TRACKS.slice().sort((a,b)=>d.scores[b.id].interest-d.scores[a.id].interest);return sciHeader('Диагностика нәтижесі','Бұл қызығушылық пен бастапқы тапсырмалардың нәтижесі. Дарындылық туралы диагноз емес.')+sciNotice(`${esc(s.grade)}-сынып · Қызығушылығың: ${esc(s.interests)}. Ұсыныс өзіндік жауаптарыңа сүйенеді; кез келген бағытты таңдай аласың.`)+`<div class="grid3" style="margin-top:20px">${ordered.map((t,i)=>`<section class="card"><span class="pill">${i<2?'Бірінші зерттеп көруге болады':'Басқа мүмкіндік'}</span><h3>${t.name}</h3><b class="score-big">${d.scores[t.id].interest}%</b><p>Неге ұсынылды: осы бағыттың екі қызығушылық сұрағына берген жауабың бойынша ${d.scores[t.id].interest}%. Бастапқы тапсырма ${d.scores[t.id].skill?'дұрыс орындалды':'қосымша үйренуді қажет етеді'}.</p><p class="muted">${t.about}</p><button class="btn ${work.chosen===t.id?'primary':''}" data-choose="${t.id}">${work.chosen===t.id?'Таңдалған бағыт':'Бағытты таңдау'} →</button></section>`).join('')}</div>`};
function sciContestPage(){const s=science();return sciHeader('3. Конкурс және ережелер','Әр ереженің жылы мен дереккөзі көрсетілген. Расталмаған тармақты мұғалім нақтылайды.')+`<div class="two-col">${Object.entries(CONTESTS).map(([id,c])=>`<section class="card"><span class="pill">${s.contest===id?'✓ Таңдалған':c.minGrade+'–'+c.maxGrade+' сынып'}</span><h2>${c.name}</h2><p class="micro">${c.year}</p><p><a href="${c.url}" target="_blank" rel="noopener">${esc(c.source)} ↗</a>${c.pdf?` · <a href="${c.pdf}" target="_blank" rel="noopener">Ресми PDF ↗</a>`:''}</p><p class="micro">Тексерілген күн: 07.11.2026. Маусым мен өңір мерзімін мұғалім нақтылайды.</p><button class="btn primary" data-contest="${id}" ${sciEligible(id,s.grade)?'':'disabled'}>${sciEligible(id,s.grade)?'Осы конкурсты таңдау':'Сыныбыңа сәйкес келмейді'}</button><details class="module" open><summary>Негізгі талаптар</summary><ul>${c.requirements.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details><details class="module"><summary>Секциялар · ${esc(c.sectionsRef)}</summary><ol>${c.sections.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details><details class="module"><summary>Бағалау критерийлері</summary><p>${esc(c.criteriaRef)}</p>${c.criteria.length?`<table><tr><th>Критерий</th><th>Ең жоғары балл</th></tr>${c.criteria.map(([l,m])=>`<tr><td>${esc(l)}</td><td>${m}</td></tr>`).join('')}</table>`:sciNotice('Ресми балл кестесі тексерілген соң мұғалім бағалау бөліміне енгізеді.')}</details><details class="module"><summary>Жұмыстың құрылымы</summary><p>Титул → мазмұн → ${sciSections({...work,science:{...s,contest:id}}).map(x=>x[1]).join(' → ')} → дереккөздер → қосымшалар.</p></details></section>`).join('')}</div>${s.contest?`<section class="card" style="margin-top:20px"><label class="field">Жоба секциясы<select id="sci-section"><option value="">Таңда</option>${sciContest().sections.map(v=>`<option ${s.section===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><p class="micro">Алты цифрлық бағыт — жұмыс құралы. Конкурс секциясын зерттеу сұрағы мен негізгі нәтиже анықтайды.</p><button class="btn primary" data-go="topics">Тақырыпқа өту →</button></section>`:''}`}
topics=function(){const s=science();return sciHeader('2. Тақырып таңдау кестесі','Ұсынысты өзгерте аласың немесе өз тақырыбыңды енгіз. Мұғалім мақұлдағаннан кейін редактор ашылады.')+sciNotice(`Конкурс: ${sciContest()?.name||'Келесі кезеңде таңдалады'} · ${esc(s.section)}. Ұсыныстар — ${currentTrack().name} құралымен орындалатын нұсқалар; секцияға мазмұндық сәйкестігін мұғалім тексереді.`)+`<section class="card" style="margin:20px 0"><label class="field">Өз тақырыбың<input id="sci-topic-title" value="${esc(work.topic?.title)}" maxlength="180" placeholder="Зерттеуіңнің нақты атауы"></label>${sciField('question','Зерттеу сұрағы',s.question,'textarea',true)}${sciField('goal','Мақсат',s.goal,'textarea',true)}${sciField('feasibility','Орындау мүмкіндігі: уақыт, құрал, әдіс, өлшем және қауіпсіздік',s.feasibility,'textarea',true)}${sciSaveMessage()}<button class="btn" id="sci-submit-topic">Конкурсты нақтылау / мақұлдауға жіберу →</button><p class="note">${sciTopicDecision()?.decision==='approved'?'✓ Мұғалім осы тақырыпты мақұлдады.':sciTopicDecision()?.decision==='returned'?'Мұғалім нақтылауға қайтарды: '+esc(sciTopicDecision().text):'Тақырыптың өзгеруі бұрынғы мақұлдауды жаңартуды қажет етеді.'}</p></section>`+sciSuggestedTopics()};
function sciSources(s){return `<section class="card"><h2>Пайдаланылған дереккөздер</h2><p class="muted">Тек өзің ашып, пайдаланған дереккөзді енгіз. Мәтінде [1], [2] түрінде сілтеме қой.</p><form id="sci-source"><div class="form-grid"><label class="field">Автор / ұйым<input name="author" required maxlength="160"></label><label class="field">Атауы<input name="title" required maxlength="300"></label><label class="field">Жыл<input name="year" required maxlength="30"></label><label class="field">Басылым, беттер<input name="publication" maxlength="300"></label></div><label class="field">Нақты сілтеме (болса)<input name="url" type="url" maxlength="1200"></label><button class="btn">Дереккөз қосу</button></form><ol>${s.sources.map((r,i)=>`<li>${esc([r.author,r.title,r.year,r.publication,r.url].filter(Boolean).join('. '))} <button class="link-button" data-del-source="${i}">Өшіру</button></li>`).join('')}</ol></section>`}
project=function(){const s=science();if(sciTopicDecision()?.decision!=='approved')return sciHeader('4. Ғылыми жобаны жазу','Тақырыпты алдымен мұғалім мақұлдайды.')+sciNotice('Бұрынғы мәтіндерің сақталған. Тақырып мақұлданған соң конкурс редакторы ашылады.')+'<button class="btn primary" data-go="topics">Тақырыпты нақтылау →</button>';return sciHeader('4. '+esc(work.topic?.title),'Өз сөзіңмен жаз, нақты дерекке сүйен. Әр өзгеріс автоматты сақталады.')+`<div class="two-col"><div>${sciSections().map(([k,l,d,q,e])=>`<section class="card science-section" id="sec-${k}"><h2>${l}</h2><p>${d}</p><p class="note">${q}</p><details><summary>Толтыру үлгісін көру</summary><p class="muted">${esc(e)}</p></details>${sciField('texts.'+k,l,s.texts[k],'textarea')}<span class="micro" data-count="${k}">${sciWords(s.texts[k])} сөз</span></section>`).join('')}${sciSources(s)}<section class="card science-section"><h2>Нақты кестелер</h2><form id="sci-table"><label class="field">Кесте атауы<input name="title" required maxlength="180"></label><label class="field">Дереккөз / өз өлшеуіңнің күні<input name="source" required maxlength="300"></label><label class="field">Кесте: ұяшықтарды Tab не ; арқылы, жолдарды Enter арқылы бөл<textarea name="text" required maxlength="16000" placeholder="Нұсқа;Көрсеткіш;Бірлік"></textarea></label><button class="btn">Кестені қосу</button></form>${s.tables.map((t,i)=>`<details class="module"><summary>Кесте ${i+1}. ${esc(t.title)}</summary><div class="scroll"><table>${t.rows.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')}</table></div><p>${esc(t.source)}</p><button class="btn" data-del-table="${i}">Өшіру</button></details>`).join('')}</section><section class="card science-section"><h2>Суреттер және дәлелдер</h2><label class="field">Суретті қосу<input id="sci-image" type="file" accept="image/png,image/jpeg"></label><p class="micro">PNG/JPEG, 5 МБ-қа дейін. Сақтау алдында кішірейтіледі; түпнұсқасын өзіңде сақта.</p><div class="grid3">${s.images.map((im,i)=>`<figure><img class="evidence-image" src="${esc(im.data)}" alt="${esc(im.caption)}">${sciField('images.'+i+'.caption','Сурет '+(i+1)+' атауы',im.caption)}${sciField('images.'+i+'.source','Дереккөзі / түсірілген күн',im.source)}<button class="btn" data-del-image="${i}">Өшіру</button></figure>`).join('')}</div></section><section class="card science-section"><h2>Қажетті қосымшалар</h2><p class="muted">Бос үлгіні нәтиже ретінде көрсетпе. Түпнұсқа анықтамалар мен қолдарды мұғалім тексереді.</p>${SCI_APPENDICES.filter(([k])=>s.contest==='zerde'||['supervisor','ethics','aiDeclaration','contribution'].includes(k)).map(([k,l])=>sciField('appendices.'+k,l,s.appendices[k],'textarea')).join('')}<label class="field">Команда авторлары (әр жолда бір адам, жеке жоба болса бос)<textarea id="sci-team" maxlength="300">${esc(s.team.join('\n'))}</textarea></label></section>${Object.keys(work.fields).length?`<details class="card science-section"><summary>Бұрынғы жоба мәтіндері · сақталған</summary>${FIELD_LIST.map(([k,l])=>`<h3>${l}</h3><p style="white-space:pre-wrap">${esc(work.fields[k])}</p>`).join('')}</details>`:''}${sciSaveMessage('Сақтау және тарихқа нұсқа қосу')}<button class="btn" data-go="checks">Талаптарды тексеру →</button></div><aside><section class="card"><h2>Зерттеу құралдары</h2><button class="btn" data-go="labs">Алты зертхана →</button><button class="btn" data-go="experiments">Тәжірибе мен күнделік →</button><button class="btn" data-go="feedback">Мұғалім пікірлері →</button></section><section class="card science-section"><h3>Зерттеу кеңесшісі</h3><p class="micro">Ережелерге сүйенетін автоматты нұсқаулық. Сыртқы ЖИ қызметі қосылмаған.</p><button class="btn" id="sci-advice">Жобама кеңес алу</button><div id="sci-advice-result"></div><button class="btn" id="sci-ai-prompt">ЖИ-ге қауіпсіз сұрау дайындау</button><textarea id="sci-prompt" hidden readonly aria-label="ЖИ үшін сұрау"></textarea></section><section class="note science-section">Зерттеу нәтижесін, деректі, дереккөзді және сілтемені ойдан толтырма. Қолданған ЖИ көмегін декларацияда көрсет.</section></aside></div>`};
function sciChecksPage(){const checks=sciChecks(),a=checks.filter(x=>!x.manual),manual=checks.filter(x=>x.manual);return sciHeader('6. Талаптарға сәйкестік',`${a.filter(x=>x.ok).length} / ${a.length} автоматты тармақ орындалды. Мұғалім тексеруі бөлек көрсетілген.`)+`<div class="progress"><span style="width:${progress()}%"></span></div><section class="card science-section"><h2>Автоматты тексеру</h2>${a.map(x=>`<div class="check-row"><span>${x.ok?'✓':'○'}</span><div><b>${esc(x.label)}</b>${x.ok?'':`<p>${esc(x.fix)}</p><button class="link-button" data-go="${x.page}">Түзетуге өту →</button>`}</div></div>`).join('')}</section><section class="card science-section"><h2>Мұғалім тексереді</h2>${manual.map(x=>`<div class="check-row"><span>◇</span><div><b>${esc(x.label)}</b><p>${esc(x.fix)}</p></div></div>`).join('')}<p>Автоматты тексеру нақты бет санын, деректің шынайылығын немесе құжаттың түпнұсқалығын растамайды.</p></section><button class="btn primary" id="sci-submit-project">Жобаны мұғалімге бағалауға жіберу →</button>`}
function sciEventText(e){if(e.type==='snapshot')return `Сақталған нұсқа · ${e.reason||''} · ${e.part+1}/${e.total}`;if(e.type==='topicSubmission')return 'Тақырып мақұлдауға жіберілді';if(e.type==='submission')return 'Жоба бағалауға жіберілді · '+e.submission;if(e.type==='topicDecision')return 'Тақырып: '+(e.decision==='approved'?'мақұлданды':'нақтылауға қайтарылды')+' · '+(e.text||'');if(e.type==='rubric')return 'Мұғалім растаған бағалау кестесі: '+e.year+' · '+e.source;if(e.type==='review')return (e.decision==='returned'?'Түзетуге қайтарылды':'Қабылданды')+' · '+(e.text||'');return e.text||'Жазба'}
function sciHistory(rows=feedback){const es=sciEvents(rows);return `<section class="card science-section"><h2>Өзгерістер мен бағалау тарихы</h2>${es.filter(e=>e.type!=='snapshot').slice().reverse().map(e=>`<article class="module"><b>${esc(e.role==='teacher'?'Мұғалім':'Оқушы')} · ${esc(fmt(e.date))}</b><p>${esc(sciEventText(e))}</p>${e.scores?`<p>Балл: ${e.total??e.scores.reduce((a,b)=>a+b,0)} / ${e.criteria.reduce((a,b)=>a+b[1],0)}</p><ul>${e.criteria.map(([l,m],i)=>`<li>${esc(l)}: ${e.scores[i]} / ${m}</li>`).join('')}</ul>`:''}${e.perAuthor?.length?`<ul>${e.perAuthor.map(a=>`<li>${esc(a.name)}: 7-критерий ${a.scores[0]}/10; 8-критерий ${a.scores[1]}/10</li>`).join('')}</ul>`:''}${e.sectionComments?Object.entries(e.sectionComments).filter(([,v])=>v).map(([k,v])=>`<p><b>${esc(SCI_SECTIONS.find(x=>x[0]===k)?.[1]||k)}:</b> ${esc(v)}</p>`).join(''):''}</article>`).join('')||'<p>Әзірге жазба жоқ.</p>'}<h3>Сақталған жоба нұсқалары</h3>${es.filter(e=>e.type==='snapshot'&&e.part===0).slice().reverse().map(e=>`<div class="module">${esc(fmt(e.date))} · ${esc(e.reason)} <button class="btn" data-snapshot="${esc(e.group)}">Нұсқаны жүктеу (.json)</button></div>`).join('')||'<p class="micro">«Сақтау» не «Мұғалімге жіберу» кезінде толық нұсқа тіркеледі.</p>'}</section>`}
const plainScienceMessages=rows=>rows.filter(r=>!sciEvent(r));
messageList=function(rows){return legacyScience.messageList(plainScienceMessages(rows))};
feedbackPage=function(){return sciHeader('7. Мұғалімнің бағалауы және кері байланысы',sciStatus())+legacyScience.feedbackPage()+sciHistory()};
function sciExportPage(){const s=science();return sciHeader('8. Word-қа жүктеу (.docx)','Құжатта титул, жаңартылатын мазмұн, бөлімдер, кестелер, суреттер және қосымшалар болады.')+`<section class="card wide"><div class="form-grid">${[['author','Қатысушының аты-жөні'],['supervisor','Ғылыми жетекші'],['school','Ұйым / мектеп'],['city','Қала / елді мекен'],['venue','Конкурс өтетін қала'],['year','Жыл'],['code','Тіркеу коды (шифр)'],['direction','Бағыт (ЖМБ / ҚГБ)']].map(([k,l])=>sciField('title.'+k,l,s.title[k]||'')).join('')}</div>${sciSaveMessage()}<label class="field">Экспорт данасы<select id="sci-export-mode"><option value="full">Мектеп / ұйымдастырушыға толық дана</option value="jury">Қазыларға дараланбаған дана · Зерде</option></select></label><button class="btn primary" id="sci-docx">Word-қа жүктеу (.docx)</button><p class="note">Word-та құжатты ашқанда мазмұн өрісін жаңартыңыз (F9 / «Обновить поле»). Нақты бет саны мен рәсімдеуді мұғалім тексереді. «Зерде» қазылар данасын экспорттағанда мәтін мен сурет ішіндегі жеке деректі де тексеру қажет.</p>${sciContest()?.formatVerified?'':sciNotice('«Дарын» үшін қаріп пен жиектер — мектептің жұмыс үлгісі. Ресми PDF бұл өлшемдерді анықтамайды.')}<button class="btn" data-go="checks">Тексеру тізімін ашу →</button></section>`}
portfolio=function(){return legacyScience.portfolio()+`<section class="card science-section"><button class="btn primary" data-go="export">Word-қа жүктеу (.docx) →</button></section>`};
review=function(){const student=roster.find(x=>x.id===selectedStudent)||roster[0];if(!student)return legacyScience.review();selectedStudent=student.id;const rows=rosterFeedback.filter(r=>r.student_id===student.id),w=sciReviewWork(student.work||emptyWork(),rows),s=science(w),criteria=sciCriteria(w);return heading(esc(student.name)+' · ғылыми жоба',esc(w.topic?.title||'Тақырып таңдалмаған'),'МҰҒАЛІМ ПАНЕЛІ')+`<label class="field">Оқушы<select id="review-student">${roster.map(r=>`<option value="${esc(r.id)}" ${r.id===student.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><button class="btn" id="refresh-roster">Деректерді жаңарту ↻</button><div class="two-col science-section"><div><section class="card"><h2>Тақырыпты мақұлдау</h2><p>Конкурс: ${esc(sciContest(w)?.name)} · ${esc(s.grade)}-сынып · ${esc(s.section)}</p><p><b>Сұрақ:</b> ${esc(s.question)}</p><p><b>Мақсат:</b> ${esc(s.goal)}</p><p><b>Мүмкіндік:</b> ${esc(s.feasibility)}</p><form id="sci-topic-review"><label class="field">Нақты пікір<textarea name="text" maxlength="2500" required></textarea></label><button class="btn primary" name="decision" value="approved">Тақырыпты мақұлдау</button><button class="btn" name="decision" value="returned">Нақтылауға қайтару</button></form></section><section class="card science-section"><h2>Конкурс мәтіні</h2><p class="note">${s.submission?'Бағалауға жіберілген сақталған нұсқа: '+esc(s.submission):'Оқушының ағымдағы жобасы · әлі бағалауға жіберілмеген'}</p>${sciSections(w).map(([k,l])=>`<details class="module" open><summary>${l}</summary><p style="white-space:pre-wrap">${esc(s.texts[k]||'Толтырылмаған')}</p></details>`).join('')}${s.tables.map((t,i)=>`<h3>Кесте ${i+1}. ${esc(t.title)}</h3><div class="scroll"><table>${t.rows.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')}</table></div><p>${esc(t.source)}</p>`).join('')}${s.images.map((im,i)=>`<figure><img class="evidence-image" src="${esc(im.data)}" alt="${esc(im.caption)}"><figcaption>${i+1}. ${esc(im.caption)} · ${esc(im.source)}</figcaption></figure>`).join('')}<h3>Дереккөздер</h3><ol>${s.sources.map(r=>`<li>${esc([r.author,r.title,r.year,r.publication,r.url].filter(Boolean).join('. '))}</li>`).join('')}</ol><h3>Қосымшалар</h3>${SCI_APPENDICES.map(([k,l])=>`<details class="module"><summary>${l}</summary><p style="white-space:pre-wrap">${esc(s.appendices[k]||'Толтырылмаған')}</p></details>`).join('')}<h3>Күнделік</h3>${w.journal.map(j=>`<p>${esc(fmt(j.date))}: ${esc(j.text)}</p>`).join('')}${experimentAnalysis(w)}<h3>Бұрынғы жоба материалдары</h3>${FIELD_LIST.filter(([k])=>w.fields[k]).map(([k,l])=>`<details class="module"><summary>${l}</summary><p>${esc(w.fields[k])}</p></details>`).join('')}${Object.entries(w.labs).map(([k,v])=>`<details class="module"><summary>${esc(TRACKS.find(t=>t.id===k)?.name)} · прототип</summary><button class="btn" data-review-lab="${k}">Визуалды түрде ашу</button><pre>${esc(JSON.stringify(v,null,2))}</pre></details>`).join('')}</section></div><aside><section class="card"><h2>Бөлімдерге пікір және бағалау</h2><p>${esc(sciStatus(w,rows))}</p><form id="sci-review">${sciSections(w).map(([k,l])=>`<label class="field">${l}: пікір<textarea name="comment-${k}" maxlength="500"></textarea></label>`).join('')}<p class="micro">${s.contest==='zerde'?'Ресми 100 балдық кесте · №153, 2-қосымша.':'Ресми балл кестесі расталмайынша сандық баға қойылмайды.'}</p>${criteria.filter((_,i)=>s.contest!=='zerde'||s.team.length<2||i<6).map(([l,m],i)=>`<label class="field">${esc(l)} · 0–${m}<input name="score${i}" type="number" min="0" max="${m}" step="1" required value="0"></label>`).join('')}${s.contest==='zerde'&&s.team.length===2?`<fieldset><legend>Әр авторға жеке баға</legend>${s.team.map((name,i)=>`<h3>${esc(name)}</h3><label class="field">7. Презентация (0–10)<input name="author${i}-7" type="number" min="0" max="10" step="1" required value="0"></label><label class="field">8. Сұрақ, түсіну, жеке үлес (0–10)<input name="author${i}-8" type="number" min="0" max="10" step="1" required value="0"></label>`).join('')}<p class="micro">Қорытынды = ортақ 1–6 балл + екі автордың жеке балдарының орташа мәні.</p></fieldset>`:''}<fieldset><legend>Мұғалім тексеретін тармақтар</legend>${sciChecks(w,rows).filter(x=>x.manual).map(x=>`<label class="manual-check"><input type="checkbox" name="manual-${x.id}"> ${esc(x.label)}</label>`).join('')}</fieldset><label class="field">Қорытынды пікір және келесі нақты қадам<textarea name="text" maxlength="1500" required></textarea></label><button class="btn primary" name="decision" value="approved" ${s.submission?'':'disabled'}>Жобаны қабылдау</button><button class="btn" name="decision" value="returned">Түзетуге қайтару</button></form></section>${s.contest==='daryn'?`<section class="card science-section"><h3>Ресми балл кестесін енгізу</h3><form id="sci-rubric"><label class="field">Ресми құжаттың HTTPS сілтемесі<input name="source" type="url" required></label><label class="field">Ереже жылы<input name="year" required maxlength="30"></label><label class="field">Әр жол: критерий;ең жоғары балл<textarea name="criteria" required maxlength="2000"></textarea></label><button class="btn">Ресми кестені сақтау</button></form><p class="micro">Кесте мұғалім авторлығымен тарихта сақталады.</p></section>`:''}${sciHistory(rows)}</aside></div>`};
let sciCheckpointPending=null,sciChangeSeq=0;
const previousScienceSchedule=scheduleSave;
scheduleSave=function(){sciChangeSeq++;previousScienceSchedule()};
function sciSnapshotRecords(w,reason,event){const text=JSON.stringify(w),group=crypto.randomUUID(),total=Math.ceil(text.length/2200);return [...Array.from({length:total},(_,part)=>({type:'snapshot',group,part,total,reason,chunk:text.slice(part*2200,(part+1)*2200)})),...(event?[event]:[])]}
function sciSnapshotWrites(store,u,w,checkpoint){return sciSnapshotRecords(w,checkpoint.reason,checkpoint.event).map(e=>{const id=crypto.randomUUID();return store.write('feedback/'+id,{id,studentId:u.id,teacherId:u.teacherId,authorId:u.id,authorName:u.name,authorRole:'student',text:SCI_PREFIX+JSON.stringify(e),rubric:null,createdAt:new Date().toISOString()},{exists:false})})}
persist=async function(){const snapshot=structuredClone(work),checkpoint=sciCheckpointPending,savedSeq=sciChangeSeq;sciCheckpointPending=null;const owner=user?.id;if(demo){const saved=demoStore();saved.work=snapshot;if(checkpoint){saved.feedback??=[];for(const event of sciSnapshotRecords(snapshot,checkpoint.reason,checkpoint.event))saved.feedback.push({id:crypto.randomUUID(),student_id:'demo-student',author_role:'student',author_name:user.name,body:SCI_PREFIX+JSON.stringify(event),created_at:new Date().toISOString()});feedback=saved.feedback}setDemo(saved);pendingSave=false;return}saveChain=saveChain.catch(()=>{}).then(async()=>{if(owner!==user?.id)throw Error('Аккаунт өзгерді. Қайта кіріңіз.');try{const r=await api('work','PUT',{work:snapshot,revision,...(checkpoint?{checkpoint}:{})});revision=r.revision;if(checkpoint)feedback=(await api('feedback')).feedback;pendingSave=sciChangeSeq!==savedSeq;for(const id of ['#save-state','#sci-save-state'])if($(id))$(id).textContent='✓ Серверде сақталды'}catch(e){pendingSave=true;for(const id of ['#save-state','#sci-save-state'])if($(id))$(id).textContent='Сақталмады · қайта сақтау қажет';throw e}});return saveChain};
async function sciCheckpoint(reason,event){clearTimeout(scheduleSave.timer);sciCheckpointPending={reason,event};pendingSave=true;await persist()}
async function sciPostEvent(event){const text=SCI_PREFIX+JSON.stringify(event);if(text.length>6000)throw Error('Пікір тым көлемді. Қысқартып жазыңыз.');await sendFeedback(text)}
function sciSet(path,value){const parts=path.split('.');let target=science();for(const p of parts.slice(0,-1))target=target[p]??={};target[parts.at(-1)]=value;work.submitted=false;scheduleSave()}
function sciAdvice(w=work){const s=science(w),missing=sciChecks(w).filter(x=>!x.ok&&!x.manual).slice(0,4);return ['Бір ғана негізгі сұрақ пен өлшенетін көрсеткішке назар аудар.',...missing.map(x=>x.fix),w.experiments.length<2?'Салыстыру үшін бірдей шартта бірнеше рет өлше; модельдік нәтижені нақты өлшеуден ажырат.':'Әр қорытындыны кестедегі нақты жолмен байланыстыр.','Мен деректерді, нәтижелерді немесе сілтемелерді толықтырмаймын. Нақты материалды мұғаліммен тексер.']}
async function sciCompress(file){if(!['image/png','image/jpeg'].includes(file.type)||file.size>5*1024*1024)throw Error('PNG/JPEG суретін таңдаңыз, ең көбі 5 МБ.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();let data=canvas.toDataURL('image/jpeg',.75);for(let q=.6;data.length>60000&&q>=.2;q-=.15)data=canvas.toDataURL('image/jpeg',q);if(data.length>60000)throw Error('Сурет тым үлкен. Өлшемін кішірейтіп жүктеңіз.');return {data,width:canvas.width,height:canvas.height,caption:file.name.slice(0,180),source:''}}
function sciSnapshot(group,rows){const chunks=sciEvents(rows).filter(e=>e.role==='student'&&e.type==='snapshot'&&e.group===group).sort((a,b)=>a.part-b.part);if(!chunks.length||chunks.length!==chunks[0].total||chunks.some((x,i)=>x.part!==i||x.total!==chunks.length))throw Error('Нұсқа толық жүктелмеген. Деректерді жаңартыңыз.');return JSON.parse(chunks.map(x=>x.chunk).join(''))}
bind=function(){legacyScience.bind();const on=(sel,fn)=>{const el=$(sel);if(el)el.onclick=async e=>{if(sciBusy)return;sciBusy=true;el.disabled=true;try{await fn(e)}catch(err){toast(err.message)}finally{sciBusy=false;el.disabled=false}}};const form=(sel,fn)=>{const el=$(sel);if(el)el.onsubmit=async e=>{e.preventDefault();if(sciBusy)return;sciBusy=true;try{await fn(e,new FormData(el))}catch(err){toast(err.message)}finally{sciBusy=false}}};
 $$('[data-sci]').forEach(el=>el.oninput=()=>{sciSet(el.dataset.sci,el.value);if(el.dataset.sci.startsWith('texts.')){const k=el.dataset.sci.split('.')[1],n=$(`[data-count="${k}"]`);if(n)n.textContent=sciWords(el.value)+' сөз'}});
 form('#sci-onboarding',async(e,f)=>{const s=science();s.grade=String(f.get('grade'));s.interests=String(f.get('interests')).trim();if(!s.interests)throw Error('Қызығушылығыңды жаз.');await persist();render()});
 // Existing skill answers retain their indices for compatibility; primary questions are simpler.
 if(sciJunior()&&$('#diag-next'))on('#diag-next',async()=>{if(diagAnswers[diagStep]===undefined)return;if(diagStep===17){const scores=calculateDiagnostic(diagAnswers);TRACKS.forEach((t,i)=>scores[t.id].skill=diagAnswers[12+i]===JUNIOR_SKILLS[i].a?100:0);work.diagnostic={scores,answers:{...diagAnswers},grade:science().grade,version:'primary-2026',date:new Date().toISOString()};if(!work.chosen)work.chosen=TRACKS.slice().sort((a,b)=>scores[b.id].interest-scores[a.id].interest)[0].id;await persist();diagStep=18;render()}else{diagStep++;render()}});
 $$('[data-choose]').forEach(el=>on(`[data-choose="${el.dataset.choose}"]`,async()=>{work.chosen=el.dataset.choose;labTrack=work.chosen;await persist();go('topics')}));
 $$('[data-contest]').forEach(el=>on(`[data-contest="${el.dataset.contest}"]`,async()=>{const s=science();if(!sciEligible(el.dataset.contest,s.grade))throw Error('Конкурс сыныпқа сәйкес емес.');if(s.contest!==el.dataset.contest){s.contest=el.dataset.contest;s.section='';work.submitted=false}await persist();render()}));
 if($('#sci-section'))$('#sci-section').onchange=async e=>{science().section=e.target.value;work.submitted=false;await persist();toast('Секция сақталды.')};
 $$('[data-topic]').forEach(el=>on(`[data-topic="${el.dataset.topic}"]`,async()=>{const t=TOPICS.find(x=>x.id===el.dataset.topic);if(!t)return;work.topic=structuredClone(t);science().question=t.question;science().goal='';science().feasibility=t.method+' Уақыт: '+t.weeks+' апта. Өлшем: '+t.metric;work.submitted=false;await persist();render()}));
 if($('#sci-topic-title'))$('#sci-topic-title').oninput=e=>{work.topic??={id:'custom',track:work.chosen};work.topic.title=e.target.value;work.submitted=false;scheduleSave()};
 on('#sci-submit-topic',async()=>{const s=science();if(!s.contest||!s.section){await persist();go('contest');toast('Тақырып сақталды. Конкурс пен секцияны таңда.');return}if(!sciEligible(s.contest,s.grade)||!work.topic?.title?.trim()||![s.question,s.goal,s.feasibility].every(v=>v?.trim()))throw Error('Тақырып, сұрақ, мақсат, мүмкіндік және секцияны толтыр.');await sciCheckpoint('Тақырып мақұлдауға жіберілді',{type:'topicSubmission',fingerprint:sciFingerprint()});toast('Тақырып мұғалімге жіберілді.');go('feedback')});
 on('#sci-save',async()=>{await sciCheckpoint('Оқушы сақтаған нұсқа');toast('Толық нұсқа тарихқа сақталды.')});
 form('#sci-source',async(e,f)=>{const s=science();if(s.sources.length>=80)throw Error('Ең көбі 80 дереккөз.');const r=Object.fromEntries(f);if(r.url&&!/^https?:\/\//i.test(r.url))throw Error('Сілтеме http:// немесе https:// арқылы басталады.');s.sources.push(r);work.submitted=false;await persist();render()});
 $$('[data-del-source]').forEach(el=>on(`[data-del-source="${el.dataset.delSource}"]`,async()=>{if(!confirm('Дереккөз өшірілсе, мәтіндегі нөмірлерді тексеру қажет. Өшіру керек пе?'))return;science().sources.splice(Number(el.dataset.delSource),1);work.submitted=false;await persist();render()}));
 form('#sci-table',async(e,f)=>{const rows=String(f.get('text')).trim().split(/\r?\n/).map(l=>l.split(/\t|;/).map(v=>v.trim()));if(rows.length>100||rows.some(r=>r.length>12||r.some(v=>v.length>500)))throw Error('Кесте ең көбі 100 жол × 12 баған, ұяшықта 500 таңба.');science().tables.push({title:f.get('title'),source:f.get('source'),rows});work.submitted=false;await persist();render()});
 for(const kind of ['table','image'])$$(`[data-del-${kind}]`).forEach(el=>on(`[data-del-${kind}="${el.dataset[kind==='table'?'delTable':'delImage']}"]`,async()=>{science()[kind==='table'?'tables':'images'].splice(Number(el.dataset[kind==='table'?'delTable':'delImage']),1);work.submitted=false;await persist();render()}));
 if($('#sci-image'))$('#sci-image').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const s=science();if(s.images.length>=8)throw Error('Ең көбі 8 сурет қосуға болады.');const image=await sciCompress(file);if(s.images.reduce((n,x)=>n+x.data.length,0)+image.data.length>220000)throw Error('Суреттердің жалпы көлемі шектен асты. Бұрынғы суретті кішірейт не өшір.');s.images.push(image);work.submitted=false;await persist();render()}catch(err){toast(err.message)}};
 if($('#sci-team'))$('#sci-team').oninput=e=>{science().team=e.target.value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,2);work.submitted=false;scheduleSave()};
 on('#sci-advice',async()=>{$('#sci-advice-result').innerHTML='<ul>'+sciAdvice().map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul>'});
 on('#sci-ai-prompt',async()=>{const p=$('#sci-prompt');p.hidden=false;p.value='Маған оқушы зерттеуіне бағыттаушы кеңес бер. Дайын ғылыми жұмыс, дерек, нәтиже немесе сілтеме ойлап шығарма. Алдымен тексеретін сұрақтар мен жоспарды ұсын. Конкурс: '+sciContest()?.name+'; сынып: '+science().grade+'; тақырып: '+(work.topic?.title||'')+'; зерттеу сұрағы: '+science().question+'. Жеке деректерді сұрама. Тек өзім берген дерекке сүйен.';p.select()});
 on('#sci-submit-project',async()=>{const missing=sciChecks().filter(x=>!x.manual&&!x.ok);if(missing.length)throw Error('Алдымен түзет: '+missing.slice(0,3).map(x=>x.label).join('; '));const s=science();s.submission=crypto.randomUUID();work.submitted=true;await sciCheckpoint('Бағалауға жіберілген нұсқа',{type:'submission',submission:s.submission});toast('Жоба бағалауға жіберілді.');go('feedback')});
 form('#sci-topic-review',async(e,f)=>{const student=roster.find(r=>r.id===selectedStudent),w=student?.work;if(!w?.topic)throw Error('Оқушы тақырыпты әлі енгізбеген.');const decision=e.submitter?.value;if(!['approved','returned'].includes(decision))throw Error('Шешімді таңдаңыз.');const s=science(w);if(decision==='approved'&&(!sciEligible(s.contest,s.grade)||!s.section||![s.question,s.goal,s.feasibility].every(v=>v?.trim())))throw Error('Тақырып мәліметтері толық емес.');await sciPostEvent({type:'topicDecision',fingerprint:sciFingerprint(w),decision,text:f.get('text')});toast('Тақырып бойынша шешім сақталды.');render()});
 form('#sci-review',async(e,f)=>{const student=roster.find(r=>r.id===selectedStudent),w=sciReviewWork(student.work||emptyWork(),rosterFeedback.filter(r=>r.student_id===selectedStudent)),s=science(w),criteria=sciCriteria(w),decision=e.submitter?.value;if(!['approved','returned'].includes(decision))throw Error('Шешімді таңдаңыз.');const checks=sciChecks(w,rosterFeedback.filter(r=>r.student_id===selectedStudent));if(decision==='approved'&&s.contest==='daryn'&&!criteria.length)throw Error('Алдымен ресми бағалау кестесін енгізіңіз.');if(decision==='approved'&&(!s.submission||checks.some(x=>x.manual&&!f.get('manual-'+x.id))))throw Error('Қабылдау үшін жіберілген нұсқа мен мұғалім тексеретін барлық тармақ қажет.');const isTeam=s.contest==='zerde'&&s.team.length===2,perAuthor=isTeam?s.team.map((name,i)=>({name,scores:[Number(f.get('author'+i+'-7')),Number(f.get('author'+i+'-8'))]})):[];if(perAuthor.some(a=>a.scores.some(v=>!Number.isInteger(v)||v<0||v>10)))throw Error('Әр автордың жеке балы 0–10 болуы тиіс.');const scores=criteria.map(([,max],i)=>isTeam&&i>=6?0:Number(f.get('score'+i)));if(scores.some((v,i)=>!Number.isInteger(v)||v<0||v>criteria[i][1]))throw Error('Критерий балын тексеріңіз.');await sciPostEvent({type:'review',decision,submission:s.submission||'',text:f.get('text'),sectionComments:Object.fromEntries(sciSections(w).map(([k])=>[k,String(f.get('comment-'+k)||'')])),scores,criteria,perAuthor,total:perAuthor.length?scores.slice(0,6).reduce((a,b)=>a+b,0)+perAuthor.reduce((n,a)=>n+a.scores[0]+a.scores[1],0)/2:scores.reduce((a,b)=>a+b,0),manual:checks.filter(x=>x.manual&&f.get('manual-'+x.id)).map(x=>x.id)});toast('Бағалау мен пікір тарихқа сақталды.');render()});
 form('#sci-rubric',async(e,f)=>{const criteria=String(f.get('criteria')).split(/\r?\n/).filter(Boolean).map(l=>{const [label,score]=l.split(';');return [label?.trim(),Number(score)]});if(!String(f.get('source')).startsWith('https://')||!criteria.length||criteria.length>12||criteria.some(([l,m])=>!l||!Number.isInteger(m)||m<1||m>100))throw Error('HTTPS дереккөзді және критерий;балл жолдарын тексеріңіз.');await sciPostEvent({type:'rubric',contest:'daryn',source:f.get('source'),year:f.get('year'),criteria});toast('Мұғалім растаған кесте сақталды.');render()});
 $$('[data-snapshot]').forEach(el=>on(`[data-snapshot="${el.dataset.snapshot}"]`,async()=>{const rows=user.role==='teacher'?rosterFeedback.filter(r=>r.student_id===selectedStudent):feedback;download('QabiletLab-history-'+el.dataset.snapshot+'.json',JSON.stringify(sciSnapshot(el.dataset.snapshot,rows),null,2))}));
 on('#sci-docx',async()=>{if(!sciContest()||!work.topic)throw Error('Алдымен конкурс пен тақырыпты таңда.');clearTimeout(scheduleSave.timer);await persist();const jury=$('#sci-export-mode').value==='jury';if(jury&&science().contest!=='zerde')throw Error('Дараланбаған дана «Зерде» үшін қолданылады.');if(jury&&!science().title.code?.trim())throw Error('Қазылар данасына тіркеу кодын енгіз.');const bytes=scienceDocx(work,{jury,userName:user.name});download('QabiletLab-'+science().contest+(jury?'-qazylar':'')+'.docx',bytes,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');toast('Word құжаты жүктелді.')});
};
function sciReviewWork(w,rows){const id=science(w).submission;if(!id)return w;for(const e of sciEvents(rows).filter(x=>x.type==='snapshot'&&x.part===0&&x.reason==='Бағалауға жіберілген нұсқа').reverse()){try{const snapshot=sciSnapshot(e.group,rows);if(snapshot.science?.submission===id)return snapshot}catch{}}return w}
function sciSuggestions(){const s=science(),section=s.section,base=rankTopics(work.chosen||'model',work.diagnostic?.scores?.[work.chosen]?.interest||50,work.diagnostic?.scores?.[work.chosen]?.skill||0,Number(s.grade)<=4?2:4);if(/Информатика|STEM|Техника/.test(section))return base.map(t=>({...t,id:'sci-'+t.id}));let items;
if(/Математика|математика/.test(section))items=[['Қорап өлшемдері мен материал шығыны','Көлемі бірдей қораптардың бет ауданы қалай өзгереді?','Қағаз макеттерін өлшеп, көлемі мен бет ауданын есепте.','Бет ауданы мен көлем'],['Кабинет жоспарының масштабы','Масштаб өзгергенде жоспардағы өлшем дәлдігі қалай сақталады?','Бір кабинетті екі масштабта сыз; нақты өлшеммен салыстыр.','Өлшем қатесі']];
else if(/Химия|биология|Биология/.test(section))items=[['Жапырақ өлшемдерін салыстыру','Бір өсімдік түрінің әр жерде өскен жапырақтарының өлшемі қалай ерекшеленеді?','Мұғаліммен қауіпсіз бақылау орнын таңда. Жапырақты үзбей, ұзындығын өлше; себепті дәлелдедім деп айтпа.','Жапырақ ұзындығы, бақылау орны'],['Өсімдіктің жарыққа қарай өсуін бақылау','Қалыпты бөлме жағдайында өсімдік бағыты уақыт өте қалай өзгереді?','Өсімдікке зиян келтірмей, бірдей уақытта сурет пен өлшем тірке.','Өсу бағыты, ұзындық, күн']];
else if(/Экология|Қоршаған/.test(section))items=[['Сыныптағы қағазды пайдалану','Екі аптада сыныптағы қайта қолданылған қағаз саны қалай өзгереді?','Жеке дерексіз күнделікті санақ жүргіз; екі кезеңнің шарттарын жаз.','Қайта қолданылған парақ саны'],['Мектеп ауласындағы көлеңке','Әртүрлі уақытта бір нысанның көлеңке ұзындығы қалай өзгереді?','Қауіпсіз жерде бірдей нысанды күн сайын бір уақытта өлше.','Көлеңке ұзындығы, уақыт']];
else if(/Физика|ғарыш|Жер/.test(section))items=[['Қағаз ұшақтың қанаты','Қанат пішіні бірдей шарттағы ұшу қашықтығына қалай әсер етеді?','Қауіпсіз бос жерде қағаз үлгілерді бірдей тәсілмен бірнеше рет сына.','Қашықтық, қайталау саны'],['Көлеңке мен уақыт','Күннің әр уақытында бір таяқшаның көлеңкесі қалай өзгереді?','Күнге тік қарамай, мұғаліммен қауіпсіз өлшеу жүргіз.','Уақыт, көлеңке ұзындығы']];
else if(/тілі|Тіл|Әдебиет|Литература/.test(section))items=[['Мәтіндегі сөздердің қолданылуы','Екі қысқа мәтінде таңдалған сөздер қандай жиілікпен кездеседі?','Өзің оқыған екі мәтінді дереккөзімен белгіле, сөздерді санап салыстыр.','Сөз жиілігі, мәтін ұзындығы'],['Нұсқаулық тілінің түсініктілігі','Қысқа және толық нұсқаулық әрекетті түсіндіруге қалай көмектеседі?','Мұғаліммен екі бірдей тапсырманың нұсқаулығын салыстыр; келісім мен дербес дерек ережесін сақта.','Орындау қатесі, уақыт']];
else if(/Тарих|Өлкетану|өлкетану|Этно|мұра/.test(section))items=[['Жергілікті атаулардың тарихы','Бір жер атауы екі сенімді дереккөзде қалай түсіндіріледі?','Кітапхана не архивтегі материалды салыстыр; аңыз бен құжатты бөлек белгіле.','Дереккөз сәйкестігі мен айырмасы'],['Мәдени өрнектерді салыстыру','Екі бұйымдағы өрнектің пішіні мен қолданылуы қалай ерекшеленеді?','Музейдің ашық материалын рұқсат етілген суретпен, авторы және дереккөзімен талда.','Өрнек белгілері, қолданылу жағдайы']];
else if(/Туризм|спорт|қауіпсіздік/.test(section))items=[['Мектептегі қауіпсіз маршрут','Екі қауіпсіз маршрутта кедергі саны мен жол ұзындығы қалай ерекшеленеді?','Мұғаліммен қауіпсіз аумақта маршрутты картаға түсір, өлшем мен кедергіні салыстыр.','Ұзындық, кедергі саны'],['Қауіпсіздік белгісінің көрнекілігі','Екі белгі нұсқасы бір ережені қалай түсіндіреді?','Қауіпсіз қағаз макеттерді салыстыр; қатысушы болса келісім ал.','Түсіндіру дәлдігі']];
else items=base.map(t=>[t.title,t.question,t.method,t.metric]);
return items.map(([title,question,method,metric],i)=>({id:'section-'+i,track:work.chosen,title,question,method,metric,weeks:Number(s.grade)<=4?2:4,cost:1,score:0}))}
function sciSuggestedTopics(){return `<h2>Зерттеу тақырыптарын салыстыр</h2><p class="muted">Диагностика бағытына сай ұсыныстар. Конкурс пен секцияны таңдағанда кесте нақтыланады.</p><div class="card scroll science-section"><table class="topic-selection-table"><thead><tr><th>Тақырып</th><th>Зерттеу сұрағы</th><th>Әдіс және мүмкіндік</th><th>Өлшем / мерзім</th><th>Таңдау</th></tr></thead><tbody>${sciSuggestions().map(t=>`<tr><td><b>${esc(t.title)}</b></td><td>${esc(t.question)}</td><td>${esc(t.method)}</td><td>${esc(t.metric)}<br>${t.weeks} апта</td><td><button class="btn primary" data-sci-topic="${esc(t.id)}">Таңдау</button></td></tr>`).join('')}</tbody></table></div>`}

const scienceBaseBind=bind;
bind=function(){scienceBaseBind();$$('[data-sci-topic]').forEach(el=>el.onclick=async()=>{try{const t=sciSuggestions().find(t=>t.id===el.dataset.sciTopic);if(!t)return;work.topic=structuredClone(t);const s=science();s.question=t.question;s.goal='';s.feasibility=t.method+' Уақыт: '+t.weeks+' апта. Өлшем: '+t.metric;work.submitted=false;await persist();render()}catch(err){toast(err.message)}})};
// Conversations use the existing per-student, append-only feedback permissions.
let conversationTimer=null,conversationGeneration=0,conversationLoading=false;
function conversationRows(){return user?.role==='teacher'?rosterFeedback.filter(r=>r.student_id===selectedStudent):feedback}
function conversationMessages(rows=conversationRows()){return plainScienceMessages(rows).slice().sort((a,b)=>a.created_at.localeCompare(b.created_at))}
function conversationUnread(rows=conversationRows()){const read=new Set(sciEvents(rows).filter(e=>e.type==='readReceipt'&&e.role===user?.role).flatMap(e=>e.ids||[]));return conversationMessages(rows).filter(m=>m.author_role!==user?.role&&!read.has(m.id))}
function conversationHTML(rows=conversationRows()){const messages=conversationMessages(rows),received=new Set(sciEvents(rows).filter(e=>e.type==='readReceipt'&&e.role!==user.role).flatMap(e=>e.ids||[]));return messages.length?messages.map(m=>`<article class="message ${m.author_role===user.role?'outgoing':'incoming'}"><b>${m.author_role===user.role?'Сіз':esc(m.author_name|| (m.author_role==='teacher'?'Мұғалім':'Оқушы'))}</b><time class="micro"> · ${esc(fmt(m.created_at))}</time><p style="white-space:pre-wrap">${esc(m.body)}</p>${m.author_role===user.role?`<span class="micro">${received.has(m.id)?'✓✓ Оқылды':'✓ Жіберілді'}</span>`:''}</article>`).join(''):'<p class="empty">Әзірге хабарлама жоқ. Алғашқы хабарламаны жазыңыз.</p>'}
function conversationPage(){if(user.role==='teacher'){if(!roster.length)return heading('Хабарламалар','Алдымен сыныпқа оқушы тіркеңіз.');if(!roster.some(r=>r.id===selectedStudent))selectedStudent=roster[0].id}return heading('Мұғалім мен оқушы хабарламалары','Хабарламаны жазыңыз, жіберіңіз және келген жауапты осы жерден оқыңыз.')+`<section class="card wide">${user.role==='teacher'?`<label class="field">Оқушыны таңдаңыз<select id="conversation-student">${roster.map(s=>`<option value="${esc(s.id)}" ${s.id===selectedStudent?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>`:'<p><b>Ғылыми жетекшіңізбен жеке сөйлесу</b></p>'}<div class="oneline"><button class="btn" id="conversation-refresh">Хабарламаларды жаңарту ↻</button><span class="micro" id="conversation-status" role="status">Жаңартылып тұрады · 15 секунд</span></div><div id="conversation-list" class="conversation-list" aria-live="polite" aria-label="Хабарламалар">${conversationHTML()}</div><form id="conversation-form"><label class="field">Хабарлама<textarea name="text" required maxlength="6000" placeholder="Сұрағыңызды немесе жауабыңызды жазыңыз…"></textarea></label><button class="btn primary" id="conversation-send">Хабарламаны жіберу →</button><p id="conversation-error" role="alert"></p></form></section>`}
async function conversationRefresh(generation=conversationGeneration){if(conversationLoading||!user||page!=='messages')return;conversationLoading=true;const owner=user.id,student=selectedStudent;try{let rows;if(demo)rows=(demoStore().feedback||[]).filter(r=>r.student_id==='demo-student');else rows=(await api('feedback'+(user.role==='teacher'?'?student='+encodeURIComponent(student):''))).feedback;if(generation!==conversationGeneration||user?.id!==owner||page!=='messages'||selectedStudent!==student)return;if(user.role==='teacher')rosterFeedback=[...rosterFeedback.filter(r=>r.student_id!==student),...rows];else feedback=rows;const unread=conversationUnread(rows);for(let i=0;i<unread.length;i+=50){await sciPostEvent({type:'readReceipt',ids:unread.slice(i,i+50).map(r=>r.id)});if(generation!==conversationGeneration||user?.id!==owner)return}if($('#conversation-list'))$('#conversation-list').innerHTML=conversationHTML();if($('#conversation-status'))$('#conversation-status').textContent='✓ Хабарламалар жаңартылды · 15 секунд сайын';}catch(e){if(generation===conversationGeneration&&$('#conversation-status'))$('#conversation-status').textContent='Жаңарту орындалмады: '+e.message}finally{conversationLoading=false}}
const conversationPreviousBind=bind;
bind=function(){conversationPreviousBind();clearTimeout(conversationTimer);const generation=++conversationGeneration;if(user?.role==='student'&&page==='feedback'){const app=$('#app');if(app){const link=document.createElement('button');link.className='btn primary';link.textContent='✉ Хабарламаларды ашу';link.onclick=()=>go('messages');if(app.prepend)app.prepend(link)}}
const selector=$('#conversation-student');if(selector)selector.onchange=e=>{selectedStudent=e.target.value;render()};const refresh=$('#conversation-refresh');if(refresh)refresh.onclick=()=>conversationRefresh();const form=$('#conversation-form');if(form)form.onsubmit=async e=>{e.preventDefault();const button=$('#conversation-send'),text=String(new FormData(form).get('text')||'').trim(),error=$('#conversation-error');if(!text||text.length>6000||text.startsWith(SCI_PREFIX)){error.textContent='Хабарлама мәтінін тексеріңіз (1–6000 таңба).';return}button.disabled=true;error.textContent='';try{await sendFeedback(text);form.reset?.();if($('#conversation-list'))$('#conversation-list').innerHTML=conversationHTML();await conversationRefresh();toast('Хабарлама жіберілді.')}catch(err){error.textContent='Жіберілмеді: '+err.message}finally{button.disabled=false}};
if(user&&page==='messages'&&$('#conversation-list')){conversationRefresh(generation);const tick=async()=>{if(generation!==conversationGeneration||page!=='messages'||!user)return;if(!document.hidden)await conversationRefresh(generation);if(generation===conversationGeneration)conversationTimer=setTimeout(tick,15000)};conversationTimer=setTimeout(tick,15000)}};
